class OrderIteratorConcurrentCloseTest {
	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void closeDuringKeyPreparationWithoutReplayContextDoesNotPublishPartialSort() throws Exception {
		CountDownLatch keyPreparationStarted = new CountDownLatch(1);
		CountDownLatch releaseKeyPreparation = new CountDownLatch(1);
		AtomicInteger keyEvaluations = new AtomicInteger();
		AtomicInteger rowsConsumed = new AtomicInteger();
		AtomicBoolean inputClosed = new AtomicBoolean();
		QueryEvaluationContext.Minimal context = new QueryEvaluationContext.Minimal(null);
		OrderComparator comparator = new OrderComparator(mock(EvaluationStrategy.class),
				new Order(new SingletonSet(), new OrderElem(Var.of("key"))), new ValueComparator(), context);
		List<BindingSet> rows = List.of(
				pausingKeyRow(1, keyEvaluations, keyPreparationStarted, releaseKeyPreparation),
				row(2),
				row(3));
		Iterator<BindingSet> iterator = rows.iterator();
		AbstractCloseableIteration<BindingSet> input = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return !inputClosed.get() && iterator.hasNext();
			}

			@Override
			public BindingSet next() {
				rowsConsumed.incrementAndGet();
				return iterator.next();
			}

			@Override
			protected void handleClose() {
				inputClosed.set(true);
			}
		};
		OrderIterator sorting = new OrderIterator(input, comparator);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			assertNull(QueryExecutionContext.captureReplayContext(), "this path must not depend on a replay context");
			Future<Boolean> result = executor.submit(sorting::hasNext);
			assertTrue(keyPreparationStarted.await(5, TimeUnit.SECONDS), "ORDER must enter key preparation");

			sorting.close();
			assertTrue(inputClosed.get(), "closing ORDER must close its owned input immediately");
			releaseKeyPreparation.countDown();

			var failure = assertThrows(ExecutionException.class,
					() -> result.get(5, TimeUnit.SECONDS),
					"a sort whose owner closed during key preparation must not publish a partial result");
			assertInstanceOf(QueryEvaluationException.class, failure.getCause(),
					"an in-progress evaluation reports the concurrent close to its caller");
			assertEquals(1, rowsConsumed.get(), "no new input row may be admitted after close");
			assertTrue(keyEvaluations.get() <= 2,
					"close may wait for the in-flight key, but must stop subsequent key evaluation");
		} finally {
			releaseKeyPreparation.countDown();
			sorting.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}
	}

	private static BindingSet pausingKeyRow(int key, AtomicInteger evaluations, CountDownLatch started,
			CountDownLatch release) {
		return new MapBindingSet() {
			private static final long serialVersionUID = 1L;

			{
				setBinding("key", SimpleValueFactory.getInstance().createLiteral(key));
			}

			@Override
			public Binding getBinding(String name) {
				Binding binding = super.getBinding(name);
				if (!"key".equals(name) || binding == null) {
					return binding;
				}
				return new SimpleBinding(name, binding.getValue()) {
					private static final long serialVersionUID = 1L;

					@Override
					public Value getValue() {
						if (evaluations.incrementAndGet() == 1) {
							started.countDown();
							try {
								if (!release.await(5, TimeUnit.SECONDS)) {
									throw new IllegalStateException("ORDER key preparation was not released");
								}
							} catch (InterruptedException e) {
								Thread.currentThread().interrupt();
								throw new IllegalStateException("ORDER key preparation was interrupted", e);
							}
						}
						return super.getValue();
					}
				};
			}
		};
	}

	private static BindingSet row(int key) {
		MapBindingSet row = new MapBindingSet();
		row.setBinding("key", SimpleValueFactory.getInstance().createLiteral(key));
		return row;
	}
}
